// 创建一个点光源
threeEditor.setLight('AmbientLight', { color: 0xffffff, intensity: 10 })

// 模型的着色器
loaderService.complete = model => ['流光闪电', '晶片着色', '彩虹光', '绚烂线条', '水波纹'].forEach((i, k) => {

    setTimeout(() => threeEditor.setObjectBlendShader(model, i), k * 1000)
    
})

