// 定义时间
let t = 0

// 动画函数
function animate(mesh) {

    t += 0.0002

    const point = curve.getPointAt(t % 1) // 获取当前点

    mesh.position.set(point.x, point.y, point.z) // 设置位置

    mesh.lookAt(curve.getPointAt((t + 0.01) % 1)) // 朝向下一个点

    requestAnimationFrame(() => animate(mesh)) // 递归调用

}

